from seven_desks.settings import CACHE as BUILD_ROOT, LAKE, SOURCE as REVIEW_SOURCE, FROZEN_VERSION
from seven_desks.store import version_root, connect
from pathlib import Path
import duckdb,json
root=LAKE;src=root/'meta/review/seven-followup-20261113/owners';out=(BUILD_ROOT / 'owners')
c=connect(config={'threads':2});c.execute("SET memory_limit='3GB'")
def emit(name,sql):
 c.execute('COPY ('+sql+") TO '"+str(out/(name+'.parquet'))+"' (FORMAT PARQUET,COMPRESSION ZSTD)"); print(name,flush=True)
active=json.loads((out.parent/'active.json').read_text())
frozen=out.parent/'versions'/active['data_version']/'data'/'owners'
for p in {p.name:p for p in [*frozen.glob('*.parquet'),*src.glob('*.parquet')]}.values():
 if p.name.startswith(('tmp_','_')):continue
 c.execute(f"create view {p.stem} as select * from read_parquet('{p}')")
for n in ['instruments','industry_members','industry_taxonomy']:
 c.execute(f"create view {n} as select * from read_parquet('{root}/curated/{n}/**/*.parquet',hive_partitioning=false,union_by_name=true)")
emit('names',"select symbol,name,asset_type from instruments qualify row_number() over(partition by symbol order by fetched_at desc)=1")
c.execute(f"create view names as select * from read_parquet('{out}/names.parquet')")
emit('stock_context',"select p.*,n.name,p.float_shares*p.close float_market_value from period_stock_context p left join names n using(symbol) where report_period in ('2026-06-30','2026-09-30') qualify row_number() over(partition by symbol order by report_period desc)=1")
c.execute(f"create view stock_context as select * from read_parquet('{out}/stock_context.parquet')")
emit('national_scope_stock',"""with h as(select 'medium' AS scope,* from national_stock_holdings union all select 'narrow',* from national_stock_holdings where entity_id in('hj_inv','hj_am','zj')),a as(select scope,report_period,symbol,sum(shares) shares,sum(holding_pct) holding_pct,sum(market_value) market_value,count(distinct entity_id) subject_count,string_agg(distinct entity_id,',') subjects,sum(account_count) account_count,max(industry_code) industry_code,max(industry_name) industry_name from h group by all) select a.*,n.name,p.float_shares*p.close float_market_value,case when starts_with(a.symbol,'688') then '科创板' when starts_with(a.symbol,'3') then '创业板' when ends_with(a.symbol,'.BJ') then '北交所' else '主板' end market_board from a left join names n using(symbol) left join period_stock_context p using(symbol,report_period)""")
emit('national_scope_industry',"""select scope,report_period,industry_code,max(industry_name) industry_name,sum(market_value) market_value,count(*) stock_count from read_parquet('"""+str(out/'national_scope_stock.parquet')+"') group by all")
emit('fund_industry_market',"""with f as(select report_period,industry_code,max(industry_name) industry_name,sum(market_value) market_value,count(distinct company_id) company_count,sum(stock_count) company_stock_observations from company_industry group by all),m as(select report_period,industry_code,sum(float_shares*close) float_market_value from period_stock_context group by all),a as(select f.*,market_value/sum(market_value) over(partition by report_period) weight,m.float_market_value/sum(m.float_market_value) over(partition by report_period) market_weight from f left join m using(report_period,industry_code)) select *,weight-market_weight overweight from a""")
emit('fund_market_history',"""with c as(select report_period,count(*) company_count,sum(visible_market_value) market_value,sum(fund_count) share_class_count,sum(new_count) new_count,sum(increase_count) increase_count,sum(decrease_count) decrease_count,sum(exit_count) exit_count,sum(estimated_net_change) estimated_change_value from company_period group by all),s as(select report_period,count(*) stock_count from fund_stock_crowding group by all) select * from c left join s using(report_period)""")
emit('sw_flow',"""with x as(select f.*,s.industry_code,s.industry_name from stock_fund_flow_windows f left join stock_context s using(symbol)),a as(select trade_date,industry_code,max(industry_name) industry_name,sum(main_net_inflow) net_flow,sum(turnover) turnover,sum(main_net_inflow)/nullif(sum(turnover),0) net_ratio,avg(daily_return) mean_daily_return,count(*) company_count from x group by all) select *,sum(net_flow) over(partition by industry_code order by trade_date rows between 4 preceding and current row) flow_5d,sum(net_flow) over(partition by industry_code order by trade_date rows between 19 preceding and current row) flow_20d from a""")
emit('margin_industry',"""with a as(select m.trade_date,s.industry_code,max(s.industry_name) industry_name,sum(m.margin_balance) margin_balance,sum(m.balance_change) balance_change,sum(m.margin_buy) margin_buy,count(*) sample_count from margin_security_flow m join stock_context s using(symbol) group by all) select *,sum(balance_change) over(partition by industry_code order by trade_date rows between 19 preceding and current row) balance_change_20d from a""")
emit('fund_band',"select report_period,size_band,count(*) company_count,sum(visible_market_value) market_value,sum(fund_count) fund_count,sum(estimated_net_change) estimated_change_value from company_period group by all")
emit('national_stock_changes',"""with x as(select 'medium' AS scope,* from national_changes union all select 'narrow',* from national_changes where entity_id in('hj_inv','hj_am','zj')) select scope,report_period,symbol,count(*) filter(where change_status='new_visible') new_count,count(*) filter(where change_status='increase') increase_count,count(*) filter(where change_status='decrease') decrease_count,count(*) filter(where change_status='exit_visible') exit_count,sum(estimated_change_value) estimated_change_value from x group by all""")
# Compact metadata, never scan every report period at request time.
meta={'company_ids':[r[0] for r in c.execute('select distinct company_id from company_period order by company_id').fetchall()], 'periods':[str(r[0]) for r in c.execute("select distinct report_period from national_entity_period where last_day(report_period)=report_period and month(report_period) in(3,6,9,12) and report_period>='2020-01-01' order by report_period desc").fetchall()], 'fund_periods':[str(r[0]) for r in c.execute("select distinct report_period from company_period where report_period>='2019-01-01' order by report_period desc").fetchall()], 'etf_indexes':[dict(zip(['value','label'],r)) for r in c.execute("select distinct reported_index_code,reported_index_name from etf_classification where category='broad' and reported_index_code is not null order by reported_index_name").fetchall()], 'industries':[dict(zip(['value','label'],r)) for r in c.execute("select distinct industry_code,industry_name from stock_context where industry_name is not null order by industry_name").fetchall()]}
(out/'metadata.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2))
